using TownOfHost;using Csv;using System.Reflection;class Program {static int passed;static void Check(bool b){if(!b)throw new Exception("assertion failed");}static void Test(string n,Action a){a();passed++;Console.WriteLine("PASS "+n);}static Stream Resource()=>Assembly.GetExecutingAssembly().GetManifestResourceStream("TownOfHost.Resources.string.csv");static void Main(){Translator.Init();foreach(var key in new[]{"Eliminator","EliminatorInfo","EliminatorInfoLong","EliminatorSummary","EliminatorRequiredKills","EliminatorMustSurvive"}){foreach(var lang in new[]{SupportedLangs.Japanese,SupportedLangs.English})Test(key+" "+lang,()=>{var value=Translator.GetString(key,lang);Check(value.Length>0&&!value.Contains("INVALID"));});Test(key+" fallback",()=>{foreach(var lang in Enum.GetValues<SupportedLangs>())if(lang is not SupportedLangs.Japanese and not SupportedLangs.English)Check(Translator.GetString(key,lang)=="*"+Translator.GetString(key,SupportedLangs.English));});}Test("exact Japanese requested labels",()=>{Check(Translator.GetString("Eliminator",SupportedLangs.Japanese)=="エリミネーター"&&Translator.GetString("EliminatorInfo",SupportedLangs.Japanese)=="クルーを撃ち抜け"&&Translator.GetString("EliminatorRequiredKills",SupportedLangs.Japanese)=="勝利に必要なキル数"&&Translator.GetString("EliminatorMustSurvive",SupportedLangs.Japanese)=="勝利に生存が必要");});Test("all translation rows unique with eight columns",()=>{using var input=Resource();var rows=CsvReader.ReadFromStream(input,new CsvOptions{HeaderMode=HeaderMode.HeaderPresent}).Where(r=>!r.Values[0].StartsWith("#")).ToArray();Check(rows.All(r=>r.ColumnCount==8)&&rows.Select(r=>r.Values[0]).Distinct().Count()==rows.Length);});Test("shared kill cooldown translation remains available",()=>Check(!Translator.GetString("KillCooldown",SupportedLangs.Japanese).Contains("INVALID")));Test("official English name is Eliminator",()=>Check(Translator.GetString("Eliminator",SupportedLangs.English)=="Eliminator"));Test("official summary is bilingual",()=>Check(Translator.GetString("EliminatorSummary",SupportedLangs.Japanese)=="エリミネーター"&&Translator.GetString("EliminatorSummary",SupportedLangs.English)=="Eliminator"));Test("role settings sort the new Japanese name using the existing reading rule",()=>Check(RoleSettingsReadings.Key(CustomRoles.Eliminator)=="えりみねた"));Console.WriteLine($"RESULT {passed} passed, 0 failed (actual Translator and embedded CSV)");}}
